="form-label">Sklad</label><input class="form-control" name="stock_quantity_decimal" value="<?=productAdminH($v['stock_quantity_decimal'])?>"></div><div class="col-md-2"><label class="form-label">Jednotka</label><input class="form-control" name="unit_code" value="<?=productAdminH($v['unit_code'])?>"></div><div class="col-md-2"><label class="form-label">EAN</label><input class="form-control" name="ean" value="<?=productAdminH($v['ean'])?>"></div><div class="col-md-4 form-check ms-2"><input class="form-check-input" type="checkbox" name="visible" value="1" id="visible<?=(int)$v['id']?>" <?=((int)$v['visible']===1||$v['visible']===null)?'checked':''?>><label class="form-check-label" for="visible<?=(int)$v['id']?>">Viditelná varianta</label></div><div class="col-md-5"><input class="form-control" name="reason" maxlength="1000" required placeholder="Důvod změny varianty"></div><div class="col-md-3 d-flex gap-2"><label class="form-check mt-2"><input class="form-check-input" type="checkbox" name="confirm_action" value="1" required> Potvrzuji</label><button class="btn btn-outline-primary ms-auto">Uložit variantu</button></div></form></div></div><?php endforeach;?>
